!function(){"use strict";window.__hymns=[{id:"afta7_fay",kind:"تمجيد",title:"افتح فاي بالتسبيح",sub:"تمجيد — «يا ربي يسوع المسيح»",src:{name:"موقع الأنبا تكلا (St-Takla.org) — تمجيد «افتح فاي بالتسبيح» (التنسيق الأول)",url:"https://st-takla.org/Lyrics-Spiritual-Songs/Words-of-Coptic-Alhan-Tasbeha-Kodas/Arabic-Coptic-08-El-Dorah-El-Orthodoxiah/Orthodox-Praises__068-Afta7-Fay-Bel-Tasabeeh.html"},review:{status:"needs-review",note:"منقول من لقطة شاشة للصفحة؛ التهجئة كما في المصدر، ويحتاج مطابقة نهائية مع الصفحة قبل الاعتماد"},lines:["افتح فاي بالتسبيح واقول بقلب جريح يا رب يسوع المسيح أعطني لسان فصيح","لكي اسبح اسمك واشكر فضل انعامك يا رب يسوع المسيح علمني احكامك","قدوس اسمك وعجيب وممجد فى قديسيك يا ربي يسوع المسيح ارحم صنعه يديك","مستحق ومستوجب التسابيح والتماجيد يا ربي يسوع المسيح تسبيحك حلو لذيذ","صرخت طول النهار مديت نحوك يدى يا ربي يسوع المسيح اسمك حلو عندى","جعلت اتكالى عليك يا رب لا تهملني يا ربي يسوع المسيح لا تتخلى عنى","روحك القدوس لا تنزعه منى يا ربي يسوع المسيح بمعونتك اشملنى","جرحنى العدو بسهام وجرحه فى حاق اعطنى جسدك مرهم ودمك هو لى ترياق","سبع مرات كل يوم ابارك اسمك يا ربي يسوع المسيح اجعلنى من قسمك","اشتاق نفسى اليك كالارض العطشانة يا ربي يسوع المسيح برحمتك لا تنسانه","لا تنسى بيعتنا املأها من خيراتك يا ربي يسوع المسيح ثبتها بشهاداتك","شهداتك حلوه فى حلقى كالشهد داخل فمى يا ربي يسوع المسيح اغسلنى من اثمى","نشكر صانع الخيرات نسجد للرب يسوع المسيح رب القوات فلنركع له بخشوع","رتب فينا احكامك وبقولك ثبتنا يا رب يسوع المسيح ارفع شأن كنيستنا","ارفع شأن المسيحيين فى جميع المسكونه يا رب يسوع المسيح اشملهم بمعونه","وان كنا فقراء من المال اسمك هو يكفينا يا ربي يسوع المسيح وصلاحك يغنينا","يجب لك التسبيح ينبغى لك البركات يا رب يسوع المسيح ينبوع كل الخيرات","يارب خلص شعبك وبارك ميراثك ارفع شأنهم باسمك وراثهم ملكوتك","ملكوتك يا إلهي ملكوت أبديه وسيادتك يا ملكى سياده ازليه","ازليه ومرتفعه وعجيبه هى افعالك يا رب يسوع المسيح سيد كل ممالك","ممالك الدنيا تزول والمال كل فانى يا رب يسوع المسيح ملك غير متناهى","تنتهى الممالك تفنى كنوز الامرا يا رب يسوع المسيح انت كنز الفقراء","فقراء شعبك اغنيهم والمرضى اسقيهم والايتام ربيهم من فضلك اغنيهم","اغنيهم من فضلك واوف كل المديونين يا رب يسوع المسيح انت غنى المحتاجين","ان كنا محتاجين فلنا دره ثمينه لنا الحجر الكريم يسوع غالى القيمه","غالى القيمه وكريم اغلى من الدنيا تمام اسمه يسوع المسيح الغافر كل اثام","غافر كل الذنوب سامع لمن يدعوه تعترف له كل الشعوب والملوك يسبحونه","سبحوه يا كل الامم مجدوه يا كل الشعوب يا ربي يسوع المسيح انت تبلغنا المطلوب","مطلوبنا ملكوتك ومراحمك موجوده يا ربي يسوع المسيح يا من طبعه الجوده","صاحب الجوده وكريم وليس له قط نظير يا ربي يسوع المسيح على الكل بصير","بصير ومتطلع علينا بتدابيرك يا ربي يسوع المسيح لا تحوجنا لغيرك","لا نعرف غيرك اله بانجيلك صدقنا انت هو ابن الله فى ايمانك ثبتنا","ثبتنا على الايمان وانهضنا من كل ملل يا ربي يسوع المسيح باسمك نتهلل","نتهلل بالالحان ونرتل بالمزامير يا ربي يسوع المسيح تسبيحك بهجه وسرور","سرورنا تسابيحك بهجتنا هى مجدك يا ربي يسوع المسيح العظمه لك وحدك","لك وحدك انا اخطيت وصنعت الشر امامك لتصدق فى اقوالك وتغلب فى احكامك","احكامك حق وعدل ومراحمك متسعه يا ربي يسوع المسيح ارحم نفسى المتضعه","اتضعت امام مجدك واتكلت على اقوالك يا ربي يسوع المسيح لا تطرحنى على شمالك","على شمالك لا توقفنى مع القوم الاشرار أسألك ان تقبلنى كما قبلت العشار","أصرخ بصوت العشار وانا برأس مطاطى اللهم اغفر لى الاوزار فانا عبدك الخاطى","الخطيه من طبعى وانت طبعك الاحسان ليس عبد بلا خطيه ولا سيد بلا غفران","الغفران من عندك والرحمه هى من قبلك يا ربي يسوع المسيح اهدينى الى سبلك","سبلك تاهت عنى والعمر فرغ منى أسألك ان تقبلنى والتوبه اعطنى","اعطينى التوبه والغفران ونقينى من كل عيوبى يا ربي يسوع المسيح اغفر لى ذنوبى","ذنوبى ثقلت فوق رأسى كحمل ثقيل قاسى يا ربي يسوع المسيح اشف كل حواسى","مراحمك يا الهى هى كثيره جدا مراحمك يا الهى لا يحصى لها عدد","مراحمك يا الهى اكثر من نبات الارض مراحمك يا الهى قد فاقت كل عدد","مراحمك يا الهى كقطرات الامطار مراحمك يا الهى اكثر من رمل البحار","مراحمك يا الهى كينابيع المياه مراحمك يا الهى كالانهار الجاريه","يا رب ارحم نفسى يا رب خلصنى يارب امحى اثمى بصلاحك اذكرنى","قدوس قدوس قدوس الله رب الصباؤت الخالق كل النفوس ورازقهم بالقوه","نسألك يا ملكنا ادم رئاسه بطركنا وشركاؤه اسافقتنا آمين الليلويا"]},{id:"epsalia_talabtak",kind:"إبصالية",title:"إبصالية «طلبتك من عمق قلبي»",sub:"من الإبسلمودية السنوية",src:{name:"موقع الأنبا تكلا (St-Takla.org) — الإبسلمودية السنوية: إبصالية «طلبتك من عمق قلبي» (العمود العربي)",url:"https://st-takla.org/Lyrics-Spiritual-Songs/Words-of-Coptic-Alhan-Tasbeha-Kodas/Arabic-Coptic-04-Epsalmodia-Tasbeha/Tasbe7a-Coptic-Transliteration-Annual-Psalmody/Praise-Epsalmodya-Tasbeha-015-Epsaliat-Aikooty_Talabtak.html"},review:{status:"needs-review",note:"منقول من لقطة شاشة للصفحة؛ التهجئة كما في المصدر، ويحتاج مطابقة نهائية مع الصفحة قبل الاعتماد؛ ومطابقتها لـ«إبصالية آدام لربنا يسوع» ويوم الأحد غير مؤكدة"},lines:["طلبتك من عمق قلبي: خلص عبدك: أيها المسيح إلهنا.","حل عني: رباطات الخطية: وأنقذني: أنا الخاطئ.","كن لي معينًا: لكي تخلصني: أيها الصالح: أصغ لسماعي.","فليدركني صلاحك: أعطني يا ابن الله: عاجلًا: أزمنة لذيذة.","أسترني: تحت ستر ظل جناحيك: وثبتني: يا ملك الأباد.","في ستة أيام: خلقت البرية كلها: وفي ستة أيام: قبلت الألام بالجسد.","سبع مرات كل يوم: أبارك أسمك: إشف أمراضنا: وكن معنا.","هوذا كل البرية: تمجد أسمك: أيها السيد: إصنع معنا رحمة.","لك الربوبية والسلطان: كن لي حارسًا: إلى الأنقضاء.","أسرع يا إلهي: لكي تخلصني: يا يسوع يا ابن الله: تراءف علي.","كل ركبة: تجثو أمامك: حلو هو إسمك القدوس: سيدنا إغفر لي.","كل الألسن مغا: تبارك إسمك: بثلاثة تقديسات مغا: نسألك أن ترحمنا.","رد وجهك: عن خطاياي: يا ملك المجد: أعطني سلامك.","كل أثامي: اللهم أمحها: وكل أعدائنا: يا رب حطمهم.","أنت تعرف أفكاري: وتفحص كلياتي: يا ملك السموات: إسمك مبارك.","قلبًا طاهرًا: إخلقه في: أيها الابن القدوس: طهر قلبي.","روحك القدوس: لا تنزعه مني: إسمع لضعفي: وأعني.","أمل سمعك: وإسمعني عاجلًا: وردني: أنا الضال.","ثبت لي ناموسًا: في طريق عدلك: و أفهمني: أيها النور المشرق.","ملكوتك يا إلهي: ملكوت أبدي: نسجد لك يا ابن الله: إلى الأبد.","أنت ابن الله: أمنت بك: فلنرتل لك: ونخدمك.","يا حامل خطية: العالم إرحمنا: طهرنا من خطايانا: ومن كل شرورنا.","أترك لنا: أثامنا الكثيرة: أيها الإله الحقيقي: أعطنا خلاصًا.","كل الأنفس مغا: تبارك إسمك: أعطني برودة: وأكتب أسماءنا.","تأن علي: لا تهلكني عاجلًا: إهدني إلى طريق: الأرض غير المضمحلة.","أقوم باكر: وأبارك إسمك: فلنرفعه مغا: يا ملكنا إرحمنا.","حلو عهو نيرك: وحملك خفيف: أنت المتحن: على خايقته.","في زمن مقبول: إستجب لي: لا تصنع الحكم: يا ملكنا معي.","محبوب هو إسمك القدوس: أنت هو الأول: والآخر مغا.","فرق عني كل الأبالسة: أنظر إلي يا سيدي كل حين.","إغرس فينا ثمرة عدلك: يا إلهي الحقيقي: طهر قلبي.","أعطنا سلامك الحقيقي: وإغفر لنا خطايانا: وأنعم علي بمحبتك إلى الأنقضاء."]}]}();